-- Future PostgreSQL/Supabase schema; not used by browser-local demo.
create table app_user (id uuid primary key, name text not null, role text not null);
create table organization (id uuid primary key, name text not null, type text not null, address text, latitude double precision, longitude double precision, description text);
create table resource (id uuid primary key, organization_id uuid references organization(id), name text not null, description text, category text not null, quantity numeric not null check(quantity>0), unit text not null, estimated_value numeric not null, available_from timestamptz not null, available_until timestamptz not null, address text, latitude double precision, longitude double precision, storage_type text, dietary_tags text[], image_url text, handling_notes text, status text not null);
create table mission (id uuid primary key, organization_id uuid references organization(id), title text not null, description text, people_served integer not null, budget numeric not null, deadline timestamptz not null, delivery_address text, latitude double precision, longitude double precision, status text not null, estimated_original_cost numeric, community_value numeric, remaining_gap numeric);
create table mission_requirement (id uuid primary key, mission_id uuid references mission(id), category text, quantity numeric, unit text, priority text, fulfilled_quantity numeric);
create table mission_match (id uuid primary key, mission_id uuid references mission(id), resource_id uuid references resource(id), allocated_quantity numeric, match_score numeric, status text);
create table volunteer_profile (id uuid primary key, user_id uuid references app_user(id), name text, vehicle_type text, capacity text, available_from timestamptz, available_until timestamptz, latitude double precision, longitude double precision);
create table route (id uuid primary key, mission_id uuid references mission(id), volunteer_id uuid references volunteer_profile(id), distance numeric, estimated_duration numeric, status text);
create table route_stop (id uuid primary key, route_id uuid references route(id), sequence integer, resource_id uuid references resource(id), address text, latitude double precision, longitude double precision, scheduled_time timestamptz, completed_at timestamptz);
create table funding_contribution (id uuid primary key, mission_id uuid references mission(id), amount numeric check(amount>0), sponsor_name text, created_at timestamptz default now(), simulated boolean default true);
create table impact_record (mission_id uuid primary key references mission(id), people_served integer, food_weight numeric, estimated_value_saved numeric, cash_spent numeric, partners integer, volunteer_hours numeric, miles numeric, waste_prevented numeric, estimated_co2 numeric);
